<!-- This file is generated by AI. -->

<!--
  角色选择对话框: 挑选参与配音的角色, 以及从角色上直接进入**参考音频编辑**。

  勾选启用、星标靠前、导入。点角色名会打开「编辑角色」的**精简版** (只留角色信息与参考音频,
  不显示 GSOV 权重) —— 站在这里点开一个角色的唯一理由就是"看看它有哪些参考音频、再补几条",
  而去工作台的角色列表里找同一个角色属于多绕一圈。权重仍然只在工作台里改: 它是服务端的
  本机路径, 与"挑选角色"这件事无关。

  ⚠️ 不带 `<style>` 块 —— 类名来自全局 `styles.css`。
-->

<script lang="ts">
  import { save as saveDialog } from '@tauri-apps/plugin-dialog';

  import { voiceExportCharacter, type Character } from '../commands/voice';
  import { appStore } from '../state/store.svelte';
  import { voiceController } from '../voice/controller';
  import { errorSummary } from '../voice/errorText';
  import AppDialog from './AppDialog.svelte';
  import Button from './Button.svelte';
  import CharacterEditDialog from './CharacterEditDialog.svelte';
  import Checkbox from './Checkbox.svelte';
  import ListImportDialog from './ListImportDialog.svelte';

  let {
    open,
    onClose,
    onError,
  }: {
    open: boolean;
    onClose: () => void;
    onError: (error: string | null) => void;
  } = $props();

  const tick = $derived(appStore.voiceTick);
  const characters = $derived.by(() => {
    void tick;
    return appStore.voiceCharacters;
  });

  let query = $state('');
  let message = $state<string | null>(null);
  let listImportOpen = $state(false);
  let editTarget = $state<Character | null>(null);

  /** 打开时清掉上一次的搜索与消息; 关闭时收掉叠在上面的编辑对话框 */
  let lastOpen = false;
  $effect(() => {
    if (open === lastOpen) return;
    lastOpen = open;
    if (open) {
      query = '';
      message = null;
    } else {
      editTarget = null;
    }
  });

  const visible = $derived.by(() => {
    if (!query.trim()) return characters;
    const needle = query.trim().toLowerCase();
    return characters.filter(
      (character) => character.name.toLowerCase().includes(needle) || character.id.toLowerCase().includes(needle)
    );
  });

  function report(caught: unknown): void {
    onError(errorSummary(String(caught)));
  }

  async function toggleEnabled(character: Character, enabled: boolean): Promise<void> {
    try {
      await voiceController.updateCharacter(character.id, { enabled });
    } catch (caught) {
      report(caught);
    }
  }

  async function toggleStarred(character: Character, starred: boolean): Promise<void> {
    try {
      await voiceController.updateCharacter(character.id, { starred });
    } catch (caught) {
      report(caught);
    }
  }

  /** 导入一份角色 zip (导入后按名称自动配对 GSOV 模型) */
  async function importCharacter(): Promise<void> {
    message = null;
    try {
      const result = await voiceController.importCharacter();
      if (result) {
        message =
          `已导入角色「${result.character.name}」` +
          (result.paired > 0
            ? '，已按名称自动配对 GSOV 模型'
            : '；没有自动配上 GSOV 模型（名称与整合包内的权重对不上，可手选）');
      }
    } catch (caught) {
      report(caught);
    }
  }

  async function remove(character: Character): Promise<void> {
    try {
      await voiceController.deleteCharacter(character.id);
    } catch (caught) {
      report(caught);
    }
  }

  async function exportCharacter(character: Character): Promise<void> {
    const destination = await saveDialog({
      defaultPath: `${character.name}.zip`,
      filters: [{ name: 'Zip 压缩包', extensions: ['zip'] }],
    });
    if (typeof destination !== 'string') return;
    await voiceExportCharacter(character.id, destination);
  }

  /** 打开角色编辑时始终取最新的一份数据 */
  function openEditor(id: string): void {
    editTarget = appStore.voiceCharacters.find((item) => item.id === id) ?? null;
  }
</script>

{#if open}
  <AppDialog
    title="选择角色"
    description="勾选参与配音的角色；点角色名可以编辑它的信息与参考音频。"
    size="large"
    height={600}
    compact
    {onClose}
  >
    <!-- 工具栏: 搜索占满剩余宽度, 两个导入按钮固定宽度, 因此不会换行 -->
    <div class="dialog-toolbar">
      <input class="ui-input dialog-toolbar-grow" placeholder="搜索角色…" bind:value={query} />
      <Button icon="ArrowUpload" onclick={() => void importCharacter()}>导入角色</Button>
      <Button
        icon="FolderOpen"
        title="从训练切分产物的文本清单与音频批量导入角色"
        onclick={() => (listImportOpen = true)}
      >
        从清单导入
      </Button>
    </div>

    {#if message}
      <p class="dialog-message">{message}</p>
    {/if}

    <div class="character-grid character-grid-pick dialog-scroll">
      {#if visible.length === 0}
        <p class="voice-dialog-empty">没有匹配的角色。</p>
      {/if}
      {#each visible as character (character.id)}
        <div class="character-block" class:disabled={!character.enabled}>
          <Checkbox
            checked={character.enabled}
            onchange={(next) => void toggleEnabled(character, next)}
            title="是否参与配音"
          />
          <button
            type="button"
            class="character-block-main"
            title="编辑角色信息与参考音频"
            onclick={() => openEditor(character.id)}
          >
            <span class="character-block-name">{character.name}</span>
            <span class="character-block-meta">{character.id} · 参考音频 {character.references.length}</span>
          </button>
          <Button
            appearance="bare"
            icon={character.starred ? 'StarFilled' : 'Star'}
            title={character.starred ? '取消星标' : '星标靠前'}
            onclick={() => void toggleStarred(character, !character.starred)}
          />
          <Button
            appearance="bare"
            icon="ArrowDownload"
            title="导出角色"
            onclick={() => void exportCharacter(character)}
          />
          <Button
            appearance="bare"
            className="danger-icon"
            icon="Delete"
            title="删除角色"
            onclick={() => void remove(character)}
          />
        </div>
      {/each}
    </div>

    {#snippet footer()}
      <Button onclick={onClose}>关闭</Button>
    {/snippet}
  </AppDialog>
{/if}

{#if listImportOpen}
  <ListImportDialog onClose={() => (listImportOpen = false)} onImported={(next) => (message = next)} />
{/if}

<!-- 从这里点开的是「编辑角色」的精简版: 不显示 GPT-SoVITS 权重 (那是工作台里的本机设置) -->
{#if editTarget}
  <CharacterEditDialog
    character={editTarget}
    hideModel
    models={[]}
    onClose={() => (editTarget = null)}
    onChanged={(next) => (editTarget = next)}
    onError={(next) => {
      if (next) report(next);
    }}
  />
{/if}
